













































































































































import { Component, Vue } from 'vue-property-decorator'
import HeadLable from '@/components/HeadLable/index.vue'
import { getEmployeeList, enableOrDisableEmployee, getRoleLevelOptions, getEmployeeRoleInfo, upgradeEmployeeRole } from '@/api/employee'
import { handleCatchError } from '@/utils/request'
import { UserModule } from '@/store/modules/user'
import InputAutoComplete from '@/components/InputAutoComplete/index.vue'
import Empty from '@/components/Empty/index.vue'

interface RoleLevelOption {
  value: number
  label: string
  description: string
}

@Component({
  name: 'Employee',
  components: {
    HeadLable,
    InputAutoComplete,
    Empty,
  },
})
export default class extends Vue {
  private input: any = ''
  private counts: number = 0
  private page: number = 1
  private pageSize: number = 10
  private tableData = []
  private id = ''
  private status = ''
  private isSearch: boolean = false

  // 权限对话框相关
  private roleDialogVisible: boolean = false
  private roleLoading: boolean = false
  private roleLevelOptions: RoleLevelOption[] = []
  private roleForm = {
    employeeId: 0,
    name: '',
    username: '',
    currentRole: 1,
    newRole: 1
  }

  created() {
    this.init()
    // 如果是SUPER用户，预加载权限选项
    if (this.isSuper) {
      this.loadRoleLevelOptions()
    }
  }

  initProp(val) {
    this.input = val
    this.initFun()
  }

  initFun() {
    this.page = 1
    this.init()
  }

  get userName() {
    return UserModule.username
  }

  // 是否是SUPER用户
  get isSuper() {
    return UserModule.isSuper
  }

  private async init(isSearch?: boolean) {
    this.isSearch = isSearch
    const params = {
      page: this.page,
      pageSize: this.pageSize,
      name: this.input ? this.input : undefined,
    }
    await getEmployeeList(params)
      .then((res: any) => {
        if (String(res.data.code) === '1') {
          this.tableData = res.data && res.data.data && res.data.data.records
          this.counts = res.data.data.total
        }
        // if (!res.data.data.records.length && type === 'search') {
        //   this.$message.error('未搜索到相关员工，请核对员工姓名是否正确')
        // }
      })
      .catch((err) => {
        handleCatchError(err)
      })
  }

  // 添加
  private addEmployeeHandle(st: string, username: string) {
    if (st === 'add') {
      this.$router.push({ path: '/employee/add' })
    } else {
      if (username === 'admin') {
        return
      }
      this.$router.push({ path: '/employee/add', query: { id: st } })
    }
  }

  //状态修改
  private statusHandle(row: any) {
    if (row.username === 'admin') {
      return
    }
    this.id = row.id
    this.status = row.status
    this.$confirm('确认调整该账号的状态?', '提示', {
      confirmButtonText: '确定',
      cancelButtonText: '取消',
      type: 'warning',
    }).then(() => {
      enableOrDisableEmployee({ id: this.id, status: !this.status ? 1 : 0 })
        .then((res) => {
          if (String(res.status) === '200') {
            this.$message.success('账号状态更改成功！')
            this.init()
          }
        })
        .catch((err) => {
          handleCatchError(err)
        })
    })
  }

  private handleSizeChange(val: any) {
    this.pageSize = val
    this.init()
  }

  private handleCurrentChange(val: any) {
    this.page = val
    this.init()
  }

  // ===== 权限管理相关方法 =====

  // 加载权限等级选项
  private async loadRoleLevelOptions() {
    try {
      const res: any = await getRoleLevelOptions()
      if (String(res.data.code) === '1') {
        this.roleLevelOptions = res.data.data
      }
    } catch (err) {
      console.error('加载权限选项失败', err)
    }
  }

  // 打开权限修改对话框
  private async openRoleDialog(row: any) {
    if (row.username === 'admin') {
      return
    }
    
    // 如果还没加载权限选项，先加载
    if (this.roleLevelOptions.length === 0) {
      await this.loadRoleLevelOptions()
    }

    try {
      const res: any = await getEmployeeRoleInfo(row.id)
      if (String(res.data.code) === '1') {
        const roleInfo = res.data.data
        this.roleForm = {
          employeeId: roleInfo.id,
          name: roleInfo.name,
          username: roleInfo.username,
          currentRole: roleInfo.role,
          newRole: roleInfo.role
        }
        this.roleDialogVisible = true
      }
    } catch (err) {
      this.$message.error('获取员工权限信息失败：' + (err as Error).message)
    }
  }

  // 关闭权限对话框
  private closeRoleDialog() {
    this.roleDialogVisible = false
    this.roleForm = {
      employeeId: 0,
      name: '',
      username: '',
      currentRole: 1,
      newRole: 1
    }
  }

  // 提交权限修改
  private async submitRoleChange() {
    if (this.roleForm.newRole === this.roleForm.currentRole) {
      this.$message.warning('权限等级未改变')
      return
    }

    this.roleLoading = true
    try {
      const res: any = await upgradeEmployeeRole({
        employeeId: this.roleForm.employeeId,
        newRole: this.roleForm.newRole
      })
      if (String(res.data.code) === '1') {
        this.$message.success('权限修改成功')
        this.closeRoleDialog()
        this.init()
      } else {
        this.$message.error(res.data.msg || '权限修改失败')
      }
    } catch (err) {
      this.$message.error('权限修改失败：' + (err as Error).message)
    } finally {
      this.roleLoading = false
    }
  }

  // 获取角色名称
  private getRoleName(role: number): string {
    const option = this.roleLevelOptions.find(o => o.value === role)
    if (option) {
      return option.description
    }
    switch (role) {
      case 9: return '超级管理员'
      case 5: return '经理'
      case 1: return '普通员工'
      default: return '未知'
    }
  }

  // 获取角色标签类型
  private getRoleTagType(role: number): string {
    switch (role) {
      case 9: return 'danger'
      case 5: return 'warning'
      case 1: return 'info'
      default: return 'info'
    }
  }
}
